    static class ECycleSort {
        int n;
        int[] a;

        public void solve(int testNumber, FastInput in, FastOutput out) {
            n = in.readInt();
            int s = in.readInt();
            a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = in.readInt();
            }
            int[] b = a.clone();
            Randomized.shuffle(b);
            Arrays.sort(b);
            int[] same = new int[n];
            int sum = 0;
            for (int i = 0; i < n; i++) {
                if (a[i] == b[i]) {
                    same[i] = 1;
                }
            }
            for (int x : same) {
                sum += x;
            }
            if (n - sum > s) {
                out.println(-1);
                return;
            }
            IntegerList permList = new IntegerList(n);
            for (int i = 0; i < n; i++) {
                if (same[i] == 0) {
                    permList.add(i);
                }
            }
            int[] perm = permList.toArray();
            CompareUtils.quickSort(perm, (x, y) -> Integer.compare(a[x], a[y]), 0, perm.length);
            DSU dsu = new DSU(n);
            for (int i = 0; i < perm.length; i++) {
                int from = perm[i];
                int to = permList.get(i);
                dsu.merge(from, to);
            }
            for (int i = 1; i < perm.length; i++) {
                if (a[perm[i]] != a[perm[i - 1]]) {
                    continue;
                }
                if (dsu.find(perm[i]) == dsu.find(perm[i - 1])) {
                    continue;
                }
                dsu.merge(perm[i], perm[i - 1]);
                SequenceUtils.swap(perm, i, i - 1);
            }
            IntegerList first = new IntegerList();
            if (perm.length > 0) {
                int remain = s - (n - sum) - 1;
                first.add(perm[0]);
                for (int i = 1; remain > 0 && i < perm.length; i++) {
                    if (dsu.find(perm[i - 1]) != dsu.find(perm[i])) {
                        remain--;
                        first.add(perm[i]);
                        dsu.merge(perm[i - 1], perm[i]);
                    }
                }

                int last = a[first.get(0)];
                for (int i = 1; i < first.size(); i++) {
                    int y = first.get(i);
                    int tmp = a[y];
                    a[y] = last;
                    last = tmp;
                }
                a[first.get(0)] = last;
                //System.err.println(Arrays.toString(a));
            }

            List<IntegerList> circles = new ArrayList<>();
            if (first.size() > 1) {
                circles.add(first);
            }
            circles.addAll(solve());
            out.println(circles.size());
            for (IntegerList list : circles) {
                out.println(list.size());
                for (int i = 0; i < list.size(); i++) {
                    out.append(list.get(i) + 1).append(' ');
                }
                out.println();
            }
        }

        public List<IntegerList> solve() {
            int[] b = a.clone();
            Randomized.shuffle(b);
            Arrays.sort(b);
            int[] same = new int[n];
            for (int i = 0; i < n; i++) {
                if (a[i] == b[i]) {
                    same[i] = 1;
                }
            }
            IntegerList permList = new IntegerList(n);
            for (int i = 0; i < n; i++) {
                if (same[i] == 0) {
                    permList.add(i);
                }
            }
            int[] perm = permList.toArray();
            CompareUtils.quickSort(perm, (x, y) -> Integer.compare(a[x], a[y]), 0, perm.length);
            DSU dsu = new DSU(n);
            for (int i = 0; i < perm.length; i++) {
                int from = perm[i];
                int to = permList.get(i);
                dsu.merge(from, to);
            }
            for (int i = 1; i < perm.length; i++) {
                if (a[perm[i]] != a[perm[i - 1]]) {
                    continue;
                }
                if (dsu.find(perm[i]) == dsu.find(perm[i - 1])) {
                    continue;
                }
                dsu.merge(perm[i], perm[i - 1]);
                SequenceUtils.swap(perm, i, i - 1);
            }

            int[] index = new int[n];
            for (int i = 0; i < n; i++) {
                if (same[i] == 1) {
                    index[i] = i;
                }
            }
            for (int i = 0; i < perm.length; i++) {
                index[perm[i]] = permList.get(i);
            }
            PermutationUtils.PowerPermutation pp = new PermutationUtils.PowerPermutation(index);
            List<IntegerList> circles = pp.extractCircles(2);

            return circles;
        }

    }

    static class Randomized {
        private static Random random = new Random(0);

        public static void shuffle(int[] data) {
            shuffle(data, 0, data.length - 1);
        }

        public static void shuffle(int[] data, int from, int to) {
            to--;
            for (int i = from; i <= to; i++) {
                int s = nextInt(i, to);
                int tmp = data[i];
                data[i] = data[s];
                data[s] = tmp;
            }
        }

        public static int nextInt(int l, int r) {
            return random.nextInt(r - l + 1) + l;
        }

    }

    static class SequenceUtils {
        public static void swap(int[] data, int i, int j) {
            int tmp = data[i];
            data[i] = data[j];
            data[j] = tmp;
        }

        public static boolean equal(int[] a, int al, int ar, int[] b, int bl, int br) {
            if ((ar - al) != (br - bl)) {
                return false;
            }
            for (int i = al, j = bl; i <= ar; i++, j++) {
                if (a[i] != b[j]) {
                    return false;
                }
            }
            return true;
        }

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 20];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }

    static class FastOutput implements AutoCloseable, Closeable, Appendable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput append(CharSequence csq) {
