		int n = a.length;

		Integer[] order = new Integer[n];
		for (int i = 0; i < n; i++) {
			order[i] = i;
		}

		Arrays.sort(order, Comparator.comparingInt(x -> a[x]));

		int[] perm = new int[n];
		Arrays.fill(perm, -1);
		int sum = 0;

		for (int i = 0; i < n; i++) {
			if (a[i] == a[order[i]]) {
				perm[i] = i;
			} else {
				sum++;
			}
		}

		if (sum > s) {
			out.println(-1);
			return;
		}

		for (int i = 0, j1 = 0, j2 = 0; i < sum; i++) {
			while (perm[order[j1]] == order[j1]) {
				j1++;
			}
			while (perm[j2] == j2) {
				j2++;
			}
			perm[order[j1]] = j2;
			j1++;
			j2++;
		}

		p = new int[n];
		Arrays.fill(p, -1);
		for (int i = 0; i < n; i++) {
			for (int j = i; p[j] == -1; j = perm[j]) {
				p[j] = i;
			}
		}

		int lastIdx = -1, lastVal = -1;

		for (int i = 0; i < n; i++) {
			int idx = order[i];
			if (perm[idx] == idx) {
				continue;
