					p[u] = v;
					int tmp = perm[idx];
					perm[idx] = perm[lastIdx];
					perm[lastIdx] = tmp;
				}

			}

			lastVal = a[idx];
			lastIdx = idx;
		}

		ArrayList<ArrayList<Integer>> cycles = new ArrayList<>();

		boolean[] used = new boolean[n];

