struct DSU {
  vector<int> p, r;
  vector<map<int, int>> nxt;
  int num;
  DSU(int n) : p(n), r(n), nxt(n), num(0) {
    for (auto i = (0); i <= (n - 1); ++i) p[i] = i;
  }
  int get(int i) {
    if (p[i] != i) p[i] = get(p[i]);
    return p[i];
  }
  int connect(int i, int j) {
    int x = get(i), y = get(j);
    if (x == y) return 0;
    --num;
    if (r[x] > r[y]) swap(x, y);
    p[x] = y;
    for (auto it : nxt[x]) {
      nxt[y].insert(it);
    }
    assert(nxt[y].count(i) and nxt[y].count(j));
    swap(nxt[y][i], nxt[y][j]);
    r[y] += r[x];
    return 1;
  }
};
