    parent[i] = i;
  }
}
int find_set(int v) {
  if (v == parent[v]) {
    return v;
  }
  return parent[v] = find_set(parent[v]);
}
void union_set(int v1, int v2) {
  v1 = find_set(v1);
  v2 = find_set(v2);
  parent[v1] = v2;
}
