            Randomized.shuffle(b);
            Arrays.sort(b);
            int[] same = new int[n];
            int sum = 0;
            for (int i = 0; i < n; i++) {
                if (a[i] == b[i]) {
                    same[i] = 1;
                }
            }
            for (int x : same) {
                sum += x;
            }
            if (n - sum > s) {
                out.println(-1);
                return;
            }
            IntegerList permList = new IntegerList(n);
            for (int i = 0; i < n; i++) {
                if (same[i] == 0) {
                    permList.add(i);
                }
            }
