    vector<int> firsts;
    for (int i = 0; i < m && firsts.size() < l; ++i) {
      if (used[i]) continue;
      auto cyc = getcycle(i);
      for (int i = 0; i < cyc.size(); ++i) {
        used[cyc[i]] = true;
      }
      firsts.push_back(i);
    }
    ans.push_back(firsts);
    assert(firsts.size() >= 2);
    int qb = Q[firsts.back()];
    for (int i = firsts.size() - 1; i; --i) {
      Q[firsts[i]] = Q[firsts[i - 1]];
    }
    Q[0] = qb;
  }
  fill(used.begin(), used.end(), 0);
  for (int i = 0; i < m; ++i) {
    if (used[i]) continue;
    auto cyc = getcycle(i);
    for (int i = 0; i < cyc.size(); ++i) {
      used[cyc[i]] = true;
    }
    ans.push_back(cyc);
  }
  printf("%d\n", ans.size());
  for (auto &vec : ans) {
    printf("%d\n", vec.size());
    for (int x : vec) {
      printf("%d ", pos[x]);
    }
    printf("\n");
  }
}
