  }
  for (int i = 0; i < (n); i++) par[i] = i;
  for (int i = 0; i < (n); i++) vis[i] = false;
  for (auto vec : vectors) {
    for (int i = 0; i < (vec.size()); i++) {
      int nxt = i + 1;
