vvc<int> slv1(vi a){
	int n=si(a);

	vi b=a;
	sort(all(b));
	vi idx(n);
	int pre=-1,cur=-1;
	rep(i,n){
		if(pre<b[i]){
			cur++;
			pre=b[i];
		}
		idx[i]=cur;
	}
	int s=cur+1;
	vvc<pi> g(s);
	rep(i,n){
		int x=idx[i];
		int y=idx[lwb(b,a[i])];
		if(x!=y){
			g[x].eb(y,i);
		}
	}
	vi head(s);
	auto dfs=[&](auto self,int v,vi&dst)->void{
		while(head[v]<si(g[v])){
			int to,e;tie(to,e)=g[v][head[v]++];
			self(self,to,dst);
			dst.pb(e);
		}
	};
	vvc<int> ans;
	int sum=0;
	rep(i,s){
		vi es;
		dfs(dfs,i,es);
		if(si(es)){
			reverse(all(es));
			ans.pb(es);
			sum+=si(es);
		}
	}
	for(auto es:ans){
		shift(a,es);
	}
	dmp(a);
	assert(is_sorted(all(a)));

	return ans;
}

void answer(vvc<int> ans,int lim){
	int sum=0;
	for(auto es:ans)sum+=si(es);
	if(sum<=lim){
		print(ans.size());
		for(auto es:ans){
			for(auto&e:es)e++;
			print(si(es));
			print(es);
		}
	}else{
		print(-1);
	}
	exit(0);
}

