};
Vi elems;
vector<Vert> G;
vector<Vi> cycles;
void dfs(int v) {
  while (!G[v].E.empty()) {
    int e = G[v].E.back();
    int dst = G[e].src.back();
    G[v].E.pop_back();
    G[e].src.pop_back();
    dfs(e);
    cycles.back().push_back(dst);
  }
}
bool debugCycles() {
  Vi copy = elems;
  for (auto& c : (cycles)) {
    int tmp = copy[c.back()];
    for (int i = int((c).size()) - 1; i > 0; i--) {
      copy[c[i]] = copy[c[i - 1]];
    }
    copy[c[0]] = tmp;
  }
  int last = 0;
  for (auto& first : (copy)) {
    if (last > first) return false;
    last = first;
  }
  return true;
}
void run() {
  int n, upper;
  cin >> n >> upper;
  elems.resize(n);
  for (auto& e : (elems)) cin >> e;
  Vi sorted(n);
  iota((sorted).begin(), (sorted).end(), 0);
  sort((sorted).begin(), (sorted).end(),
       [&](int l, int r) { return elems[l] < elems[r]; });
  int last = elems[sorted[0]], k = 0;
  for (int i = (0); i < (n); i++) {
    int e = sorted[i];
    if (elems[e] != last) k++;
    last = elems[e];
    elems[e] = k;
  }
  k++;
  G.resize(k);
  for (int i = (0); i < (n); i++)
    if (elems[i] != elems[sorted[i]]) {
      G[elems[i]].src.push_back(i);
      G[elems[i]].E.push_back(elems[sorted[i]]);
    }
  int len = 0;
  for (int i = (0); i < (k); i++)
    if (!G[i].E.empty()) {
      cycles.emplace_back();
      dfs(i);
      len += int((cycles.back()).size());
    }
  if (!debugCycles()) {
    cout << "euler failed\n";
  }
  if (len > upper) {
    cout << "-1\n";
    return;
  }
  int toMerge = min(int((cycles).size()), upper - len);
  if (toMerge > 2) {
    Vi one, two;
    for (int i = (0); i < (toMerge); i++) {
      one.insert(one.end(), (cycles.back()).begin(), (cycles.back()).end());
      two.push_back(cycles.back()[0]);
      cycles.pop_back();
    }
    reverse((two).begin(), (two).end());
    cycles.push_back(one);
    cycles.push_back(two);
  }
  if (!debugCycles()) {
    cout << "merge failed\n";
  }
  cout << int((cycles).size()) << '\n';
  for (auto& c : (cycles)) {
    cout << int((c).size()) << '\n';
    for (auto& first : (c)) cout << first + 1 << ' ';
    cout << '\n';
  }
}
import java.io.BufferedReader;
import java.io.BufferedWriter;
