struct Euler {
    vi circuit;
    set<pi> adj[MX];

    void addEdge(int a, pi b) {
        adj[a].insert(b);
    }

    void find_circuit(int x) { // directed graph, possible that resulting circuit is not valid
        while (sz(adj[x])) {
            pi j = *adj[x].begin(); adj[x].erase(adj[x].begin());
            find_circuit(j.f);
            circuit.pb(j.s);
        }
    }

    vector<vi> genCyc() {
        vector<vi> ans;
        F0R(i,n) if (sz(adj[i])) {
            circuit.clear();
            find_circuit(i);
            ans.pb(circuit);
        }
        return ans;
    }
};

