void calc(int v) {
  stack<int> s;
  while (true) {
    if (((int)e[v].size()) == 0) {
      circuit.push_back(v);
      if (!((int)s.size())) {
        break;
      }
      v = s.top();
      s.pop();
    } else {
      s.push(v);
      int u = e[v].back();
      e[v].pop_back();
      v = u;
    }
  }
}
