vector<int> pat[500000];
vector<int> rev[500000];
vector<bool> flag[500000];
int pt[500000];
void adde(int a, int b) {
  pat[a].push_back(b);
  flag[a].push_back(false);
}
vector<int> euler;
void calceuler(int node) {
  for (;;) {
    if (pt[node] == pat[node].size()) break;
    if (!flag[node][pt[node]]) {
      flag[node][pt[node]] = true;
      pt[node]++;
      calceuler(pat[node][pt[node] - 1]);
    } else
      pt[node]++;
  }
  euler.push_back(node);
}
class unionfind {
 public:
  int par[500000];
  int ran[500000];
  int ren[500000];
  void init() {
    for (int i = 0; i < 500000; i++) {
      par[i] = i;
      ran[i] = 0;
      ren[i] = 1;
    }
  }
  int find(int a) {
    if (a == par[a])
      return a;
    else
      return par[a] = find(par[a]);
  }
  void unite(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b) return;
    if (ran[a] > ran[b]) {
      par[b] = a;
      ren[a] += ren[b];
    } else {
      par[a] = b;
      ren[b] += ren[a];
    }
    if (ran[a] == ran[b]) ran[b]++;
  }
};
