		inputData = new StringTokenizer(reader.readLine());

		TreeSet<Integer> unique = new TreeSet<>();

		for (int i = 0; i < N; i++) {
			a[i] = Integer.parseInt(inputData.nextToken());
			unique.add(a[i]);
		}

		int cnt = 0;
		for (Integer i : unique) {
			map.put(i, cnt++);
		}

		for (int i = 0; i < N; i++) {
			a[i] = map.get(a[i]);
		}

		srt = Arrays.copyOf(a, N);
		Arrays.sort(srt);

		int nDis = 0;
		for (int i = 0; i < N; i++) {
			if (a[i] != srt[i]) {
				nDis++;
			}
		}
		if (nDis > B) {
			printer.println(-1);
			printer.close();
			return;
		}

