		for (int i = 0; i < nV; i++) {
			aList[i] = new ArrayList<>();
		}

		for (int i = 0; i < N; i++) {
			if (a[i] != srt[i]) {
				aList[N + srt[i]].add(i);
				aList[i].add(N + a[i]);
			}
		}

		visited = new boolean[nV];

		ArrayList<ArrayList<Integer>> cycles = new ArrayList<>();
		for (int i = 0; i < N; i++) {
			if (a[i] != srt[i] && !visited[i]) {
				dfs(i);
				cycles.add(order);
				order = new ArrayList<>();
			}
		}

