struct St : vector<int> {
    int pop() {
        int x = back();
        pop_back();
        return x;
    }
};

St g(const string& s) {
    string t(s.rbegin(), s.rend());
    int p = 0;
    t += 'c';
    St v;
    for (int i = 1; i < t.length(); ++i) {
        if (t[i] != t[i - 1]) {
            v.push_back(i - p);
            p = i;
        }
    }

    return v;
}

using Ans = vector<pair<int, int>>;

Ans best(const Ans& l, const Ans& r) {
    return l.size() < r.size() ? l : r;
}


bool bn, bm;

Ans eval(St l, St r) {
    Ans ans;
    int iters = max(r.size(), l.size());
    int suml = iters * 4;

    int n = l.size(), m = r.size();
    while (l.size() > 1 || r.size() > 1) {
        assert(iters--);

        if (l.empty()) {
            l.push_back(0);
        }

        if (r.empty()) {
            r.push_back(0);
        }

        St adl;
        adl.push_back(l.pop());
        St adr;
        adr.push_back(r.pop());

        while (l.size() + adr.size() + 1 < r.size() + adl.size()) {
            adr.push_back(r.pop());
            adr.push_back(r.pop());
        }

        while (r.size() + adl.size() + 1 < l.size() + adr.size()) {
            adl.push_back(l.pop());
            adl.push_back(l.pop());
        }

        ans.emplace_back(accumulate(adl.begin(), adl.end(), 0), accumulate(adr.begin(), adr.end(), 0));

        suml -= adl.size();
        suml -= adr.size();

        if (suml < 0) {
            exit(0);
        }

        if (!l.empty()) {
            l.back() += adr.pop();
        } 

        l.insert(l.end() ,adr.rbegin(), adr.rend());

        if (!r.empty()) {
            r.back() += adl.pop();
        }

        r.insert(r.end(), adl.rbegin(), adl.rend());    
    }

    return ans;
}

