					printer.print(cCycle.get(i) + 1 + " ");
				}
			}
			printer.println();
		}
		printer.close();
	}

	static void dfs(int i) {
		visited[i] = true;

		while (!aList[i].isEmpty()) {
			int lInd = aList[i].size() - 1;
			int nxt = aList[i].get(lInd);
			aList[i].remove(lInd);
			dfs(nxt);
		}
		order.add(i);
	}

