void compress() {
  pair<int, int> p[max_n];
  for (int i = 0; i < n; ++i) {
    p[i] = {a[i], i};
  }
  sort(p, p + n);
  int num = 0;
  for (int i = 0; i < n;) {
    int start = i;
    while (i < n && p[i].first == p[start].first) {
