using namespace std;
vector<pair<int, int> > adj[200000];
int nxt[200000];
bool v[200000];
vector<int> cycle;
void dfs(int now) {
  v[now] = true;
  while (nxt[now] < adj[now].size()) {
    cycle.push_back(adj[now][nxt[now]].second);
    nxt[now]++;
    dfs(adj[now][nxt[now] - 1].first);
  }
}
void dfs2(int now) {
  v[now] = true;
  for (int i = 0; i < adj[now].size(); i++) {
    int to = adj[now][i].first;
    if (!v[to]) {
      dfs2(to);
    }
  }
}
int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  int n, s;
  cin >> n >> s;
  vector<int> li;
  vector<int> all;
  for (int i = 0; i < n; i++) {
    nxt[i] = 0;
    v[i] = false;
    int x;
    cin >> x;
    li.push_back(x);
    all.push_back(x);
  }
  sort(all.begin(), all.end());
  map<int, int> m;
  int zone[n];
  int point = 0;
  for (int i = 0; i < n; i++) {
    if (i > 0 && all[i] == all[i - 1]) {
      continue;
    }
    for (int j = i; j < n && all[i] == all[j]; j++) {
      zone[j] = point;
    }
    m[all[i]] = point;
    point++;
  }
  for (int i = 0; i < n; i++) {
    int to = m[li[i]];
    if (to == zone[i]) {
      continue;
    }
    adj[zone[i]].push_back(make_pair(to, i + 1));
  }
  int comp = 0;
  for (int i = 0; i < point; i++) {
    if (!v[i] && adj[i].size() > 0) {
      dfs2(i);
      comp++;
    }
  }
  for (int i = 0; i < point; i++) {
    v[i] = false;
  }
  vector<vector<int> > ans;
  int tot = 0;
  for (int i = 0; i < point; i++) {
    if (v[i] || adj[i].size() == 0) {
      continue;
    }
    cycle.clear();
    dfs(i);
    tot += (int)cycle.size();
    ans.push_back(cycle);
  }
  if (tot > s) {
    cout << -1 << endl;
    return 0;
  }
  cout << ans.size() << endl;
  assert((int)ans.size() == comp);
  for (int i = 0; i < ans.size(); i++) {
    cout << ans[i].size() << endl;
    cout << ans[i][0];
    for (int j = 1; j < ans[i].size(); j++) {
      cout << " " << ans[i][j];
    }
    assert(ans[i].size() > 1);
    cout << endl;
  }
}
