ln* fe(ln* ath, int cp) {
  ln* sv = NULL;
  for (int i = roi[cp]; i < nl[cp].size(); i = roi[cp]) {
    int np = nl[cp][i].first;
    int ind = nl[cp][i].second;
    if (btdt[ind]) {
      continue;
    }
    roi[cp]++;
    btdt[ind] = 1;
    ln* cn = new ln();
    cn->val = ind;
    cn->next = NULL;
    ln* vas = fe(cn, np);
    if (sv == NULL) {
      sv = cn;
      continue;
    }
    ath->next = cn;
    ath = vas;
  }
  if (sv != NULL) {
    ath->next = sv;
    ath = sv;
  }
  return ath;
}
