int indexof(vector<int> &v, int x) {
  return upper_bound((v).begin(), (v).end(), x) - v.begin() - 1;
}
void dfs(int u) {
  vis[u] = true;
  if (!edge[u].empty()) {
    int v = edge[u].back();
    edge[u].pop_back();
    dfs(v);
  }
  tour.push_back(u);
}
void solve() {
  int k = min(M, S - n);
  if (k <= 2) {
    ans = M;
    for (auto i = (0); i < (M); i++) {
      moves[i] = cyc[i];
    }
  } else {
    ans = M - k + 2;
    for (auto i = (0); i < (M - k); i++) {
      moves[i] = cyc[i];
    }
    for (auto i = (M - k); i < (M); i++) {
      moves[M - k].insert(moves[M - k].end(), (cyc[i]).begin(), (cyc[i]).end());
      moves[M - k + 1].push_back(cyc[i][0]);
    }
