void recur(int n) {
  vis[comp[n]] = 1;
  while (comp_stack[comp[n]].size() > 0) {
    int next = comp_stack[comp[n]].back();
    comp_stack[comp[n]].pop_back();
    recur(next);
  }
  cursol.push_back(n);
  if (d) printf("add %d\n", n);
}
