using namespace std;
int a[200010], b[200010], nxt[200010], cnt, n, s;
void solve(vector<int> &v, int i, int &j) {
  while (a[j] == a[i]) j++;
  if (j >= n) return;
  if (b[j] == a[i]) {
    swap(a[i], a[j]);
    cnt++;
    v.push_back(j++);
    solve(v, i, nxt[lower_bound(b, b + n, a[i]) - b]);
  }
}
int main() {
  cin >> n >> s;
  for (int i = 0; i < n; i++) {
    scanf("%d", a + i);
