  }
  sort(b, b + n);
  a[n] = b[n] = -1;
  cnt = 0;
  vector<vector<int> > ans;
  for (int i = 0; i < n; i++) {
    if (b[i] == a[i]) continue;
    ans.push_back(vector<int>(1, i));
    cnt++;
    nxt[lower_bound(b, b + n, b[i]) - b] = i + 1;
    auto &v = ans.back();
    solve(v, i, nxt[lower_bound(b, b + n, a[i]) - b]);
    for (int k = 0; k < v.size(); k++) {
      int j0 = v[k];
      int &j = nxt[lower_bound(b, b + n, b[j0]) - b];
      while (b[j0] == b[j]) {
