struct Euler {
  struct Edge {
    long long nei, nr, id;
  };
  vector<vector<Edge>> slo;
  vector<long long> ans, used, deg, beg;
  long long e_num, n;
  Euler() : e_num(0), n(0) {}
  void AddEdge(long long a, long long b, long long idd) {
    e_num++;
    if (a > n || b > n) {
      n = max(a, b);
      slo.resize(n + 2);
      deg.resize(n + 2);
      beg.resize(n + 2);
    }
    used.push_back(0);
    slo[a].push_back({b, e_num, idd});
  }
  vector<vector<long long>> FindEuler() {
    used.push_back(0);
    assert(((long long)(used).size()) > e_num);
    vector<vector<long long>> lol;
    for (long long i = (1); i <= (n); ++i) {
      if (beg[i] < ((long long)(slo[i]).size())) {
        Go(i);
        lol.push_back(ans);
        ans.clear();
      }
    }
    return lol;
  }

 private:
  void Go(long long v) {
    (v);
    while (beg[v] < ((long long)(slo[v]).size())) {
      Edge& e = slo[v][beg[v]];
      beg[v]++;
      long long nei = e.nei;
      if (used[e.nr]) {
        continue;
      }
      used[e.nr] = 1;
      Go(nei);
      ans.push_back(e.id);
    }
  }
};
