using namespace std;
const int MAXN = 2e5 + 5;
vector<int> circuit;
vector<int> e[MAXN];
void calc(int v) {
  stack<int> s;
  while (true) {
    if (((int)e[v].size()) == 0) {
      circuit.push_back(v);
      if (!((int)s.size())) {
        break;
      }
      v = s.top();
      s.pop();
    } else {
      s.push(v);
      int u = e[v].back();
      e[v].pop_back();
      v = u;
    }
  }
}
int a[MAXN];
int b[MAXN];
int c[MAXN];
vector<int> comp;
unordered_map<int, int> act;
unordered_map<long long, vector<int> > pos;
bool bio[MAXN];
void dfs(int v) {
  if (bio[v]) return;
  bio[v] = true;
  for (auto w : e[v]) {
    dfs(w);
  }
}
vector<vector<int> > ans;
vector<vector<int> > sol;
int s;
void solve(vector<int> &start) {
  int uk = 0;
  for (auto x : start) {
    calc(x);
    uk += ((int)circuit.size()) - 1;
    reverse(circuit.begin(), circuit.end());
    ans.push_back(circuit);
    circuit.clear();
  }
  if (uk > s) {
    cout << -1;
    exit(0);
  }
  for (auto v : ans) {
    vector<int> nv;
    for (int i = 0; i < ((int)v.size()) - 1; ++i) {
      int x = v[i];
      int y = v[i + 1];
      assert(((int)pos[(long long)x * MAXN + y].size()) > 0);
      nv.push_back(pos[(long long)x * MAXN + y].back());
      pos[(long long)x * MAXN + y].pop_back();
    }
    sol.push_back(nv);
  }
}
