    static class ECycleSort {
        boolean[] visited;
        int[] index;

        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            int s = in.readInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = in.readInt();
            }
            int[] b = a.clone();
            Randomized.shuffle(b);
            Arrays.sort(b);
            byte[] same = new byte[n];
            int sum = 0;
            for (int i = 0; i < n; i++) {
                if (a[i] == b[i]) {
                    same[i] = 1;
                }
            }
            for (byte x : same) {
                sum += x;
            }
            if (n - sum > s) {
                out.println(-1);
                return;
            }
            IntegerList permList = new IntegerList(n);
            for (int i = 0; i < n; i++) {
                if (same[i] == 0) {
                    permList.add(i);
                }
            }
            int[] perm = permList.toArray();
            CompareUtils.quickSort(perm, (x, y) -> Integer.compare(a[x], a[y]), 0, perm.length);
            DSU dsu = new DSU(n);
            for (int i = 0; i < perm.length; i++) {
                int from = perm[i];
                int to = permList.get(i);
                dsu.merge(from, to);
            }
            for (int i = 1; i < perm.length; i++) {
                if (a[perm[i]] != a[perm[i - 1]]) {
                    continue;
                }
                if (dsu.find(perm[i]) == dsu.find(perm[i - 1])) {
                    continue;
                }
                dsu.merge(perm[i], perm[i - 1]);
                SequenceUtils.swap(perm, i, i - 1);
            }
            index = new int[n];
            for (int i = 0; i < n; i++) {
                if (same[i] == 1) {
                    index[i] = i;
                }
            }
            for (int i = 0; i < perm.length; i++) {
                index[perm[i]] = permList.get(i);
            }

            visited = new boolean[n];
            List<IntegerList> circles = new ArrayList<>(n / 2);
            IntegerList reuse = new IntegerList(n);
            for (int i = 0; i < n; i++) {
                if (same[i] == 1 || visited[i]) {
                    continue;
                }
                reuse.clear();
                circles.add(detect(i, reuse));
            }
            out.println(circles.size());
            for (IntegerList list : circles) {
                out.println(list.size());
                for (int i = 0; i < list.size(); i++) {
                    out.append(list.get(i) + 1).append(' ');
                }
            }
        }

        public IntegerList detect(int i, IntegerList list) {
            if (visited[i]) {
                return list.clone();
            }
            visited[i] = true;
            list.add(i);
            return detect(index[i], list);
        }

    }

    static class DSU {
        int[] p;
        int[] rank;

        public DSU(int n) {
            p = new int[n];
            rank = new int[n];
            reset();
        }

        public void reset() {
            for (int i = 0; i < p.length; i++) {
                p[i] = i;
                rank[i] = 0;
            }
        }

        public int find(int a) {
            return p[a] == p[p[a]] ? p[a] : (p[a] = find(p[a]));
        }

        public void merge(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) {
                return;
            }
            if (rank[a] == rank[b]) {
                rank[a]++;
            }
            if (rank[a] > rank[b]) {
                p[b] = a;
            } else {
                p[a] = b;
            }
        }

    }

    static class Randomized {
        private static Random random = new Random(0);

        public static void shuffle(int[] data) {
            shuffle(data, 0, data.length - 1);
        }

        public static void shuffle(int[] data, int from, int to) {
            to--;
            for (int i = from; i <= to; i++) {
                int s = nextInt(i, to);
                int tmp = data[i];
                data[i] = data[s];
                data[s] = tmp;
            }
        }

        public static int nextInt(int l, int r) {
            return random.nextInt(r - l + 1) + l;
        }

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 20];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
